package com.wenwen.service.impl;
import com.wenwen.service.AiExportService;
import com.wenwen.ai.export.*;
import com.wenwen.ai.scope.TrustedDoctor;
import com.wenwen.ai.result.AnalysisSettings;
import com.wenwen.ai.query.CohortException;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.time.*;
import java.util.*;
import java.io.*;
import org.springframework.stereotype.Service;
@Service public final class AiExportServiceImpl implements AiExportService {
    private final ExportContentReader reader;private final ExportFieldPolicy policy;private final OrdinaryXlsxWriter writer;private final ExportAuditStore audit;private final AnalysisSettings settings;private final Clock clock;private final ObjectMapper json=new ObjectMapper();
    public AiExportServiceImpl(ExportContentReader r,ExportFieldPolicy p,OrdinaryXlsxWriter w,ExportAuditStore a,AnalysisSettings s,Clock c){reader=r;policy=p;writer=w;audit=a;settings=s;clock=c;}
    @SuppressWarnings("unchecked") private static Map<String,Object> map(Object o){return (Map<String,Object>)o;}
    public OrdinaryXlsxWriter.File prepare(TrustedDoctor doctor,AiExportQuery q,String trace,Instant requestedAt)throws IOException {
        cancelled();policy.validate();int max=settings.maxBytes();long owner=doctor.getId();ExportFieldPolicy.Window window=new ExportFieldPolicy.Window(requestedAt);ExportContentReader.Content c=reader.read(owner,q,requestedAt);
        List<Map<String,Object>> blocked=policy.blocked(q,c.payload,window);
        Map<String,Object> meta=map(c.payload.get("meta")),conditions=conditions(q,c.payload);Map<String,Object> values=new LinkedHashMap<>();
        values.put("id",trace);values.put("actorDoctorId",owner);values.put("source",q.source);values.put("referenceId",q.referenceId);values.put("payloadSha256",c.hash);values.put("scopeFingerprint",c.fingerprint);values.put("selectionMode",q.selectionMode);values.put("requestedItems",encode(q.requested,1024));values.put("conditionSummary",encode(conditions,4096));values.put("sourcePolicyVersions",encode(meta.get("policyVersions"),4096));values.put("exportPolicyVersion",ExportFieldPolicy.VERSION);values.put("freeStart",window.freeStart.toString());values.put("policyToday",window.today.toString());values.put("cohortN",c.payload.get("n"));values.put("cohortAN","COMPARE".equals(q.source)?map(c.payload.get("a")).get("n"):null);values.put("cohortBN","COMPARE".equals(q.source)?map(c.payload.get("b")).get("n"):null);values.put("createdAtMs",requestedAt.toEpochMilli());values.put("generationStatus","PREPARING");values.put("transferStatus","NOT_STARTED");
        ExportAuditRecord record=new ExportAuditRecord(values);
        if(!blocked.isEmpty()){Map<String,Object> rejection=policy.rejection(q,c.payload,window,blocked);record.put("generationStatus","NEED_APPLY");record.put("errorCode","NEED_APPLY");try{record.put("finishedAtMs",clock.instant().toEpochMilli());if(!Thread.currentThread().isInterrupted())audit.insertNeedApply(record);}catch(RuntimeException e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("export trace={} operation=insertNeedApply errorCode=NEED_APPLY",trace);}throw new ExportFieldPolicy.NeedApply(rejection);}cancelled();audit.insertPreparing(record);
        OrdinaryXlsxWriter.File file;try{Map<String,Object> metadata=new LinkedHashMap<>();metadata.put("source",q.source);metadata.put("referenceId",q.referenceId);metadata.put("selectionMode",q.selectionMode);metadata.put("selected",encode(q.requested,1024));metadata.put("freeStart",window.freeStart.toString());metadata.put("today",window.today.toString());metadata.put("policyVersion",ExportFieldPolicy.VERSION);metadata.put("at",meta.get("at"));metadata.put("asOf",meta.get("asOfDate"));for(String key:Arrays.asList("readStartedAt","readCompletedAt","computedAt"))metadata.put(key,meta.get(key));metadata.put("generatedAt",clock.instant().toString());metadata.put("policyVersions",encode(meta.get("policyVersions"),4096));metadata.put("conditions",encode(conditions,4096));metadata.put("crpThresholds","2.3/2.7/4.1");metadata.put("disclosure","探索性统计；Excel计算及再次保存受双精度/有效位限制；WRITTEN不证明收到或阅读");metadata.put("selectedItemsN",q.requested.size());metadata.put("units",units(q));metadata.put("missingCells","BLANK仅表示所选保留值缺失；无可靠来源日期不会以空格替代后放行");metadata.put("statisticalDisclosure",meta.get("statisticalDisclosure"));metadata.put("status","COHORT".equals(q.source)?((Number)c.payload.get("n")).intValue()==0?"EMPTY":"DATA":((Number)map(c.payload.get("a")).get("n")).intValue()+((Number)map(c.payload.get("b")).get("n")).intValue()==0?"EMPTY":"DATA");if("COMPARE".equals(q.source)){metadata.put("aN",map(c.payload.get("a")).get("n"));metadata.put("bN",map(c.payload.get("b")).get("n"));metadata.put("comparisonTests","每指标仅第一行包含一个整体检验；类别行不是独立P值；unknown/denominator/validN沿用原引用");Map<String,Object> cover=new LinkedHashMap<>();for(String side:Arrays.asList("a","b")){Map<String,Object> selected=new LinkedHashMap<>();for(String metric:q.requested)if(!"n".equals(metric))selected.put(metric,map(map(meta.get("sourceDateCoverage")).get(side)).get(metric));cover.put(side,selected);}metadata.put("sourceDateCoverage",encode(cover,65536));}
        file=writer.write(q,c,window,metadata,max);cancelled();}catch(IOException|RuntimeException failure){String code=Thread.currentThread().isInterrupted()?"CANCELLED":failure instanceof CohortException&&"RESULT_TOO_LARGE".equals(((CohortException)failure).getCode())?"RESULT_TOO_LARGE":"SERVICE_UNAVAILABLE";try{if(!Thread.currentThread().isInterrupted())audit.markGenerationFailed(trace,owner,clock.instant().toEpochMilli(),code);}catch(RuntimeException ignored){org.slf4j.LoggerFactory.getLogger(getClass()).warn("export trace={} operation=markGenerationFailed errorCode={}",trace,code);}throw failure;}audit.markReady(trace,owner,clock.instant().toEpochMilli(),file.rows,file.bytes.length);try{cancelled();reader.requireScope(owner,c);ExportContentReader.expiry(q.source,c.expires,clock.instant());cancelled();}catch(RuntimeException failure){CohortException rejection=failure instanceof CohortException?(CohortException)failure:new CohortException(503,"SERVICE_UNAVAILABLE","导出暂不可用");try{if(!Thread.currentThread().isInterrupted())audit.rejectTransfer(trace,owner,clock.instant().toEpochMilli(),rejection.getCode());}catch(RuntimeException ignored){org.slf4j.LoggerFactory.getLogger(getClass()).warn("export trace={} operation=rejectTransfer errorCode={}",trace,rejection.getCode());}throw rejection;}audit.startTransfer(trace,owner,clock.instant().toEpochMilli());cancelled();return file;
    }
    private static String units(AiExportQuery q){List<String> out=new ArrayList<>();for(String field:q.requested){String unit=field.startsWith("das28")||"haqAt".equals(field)?"score":field.startsWith("crp")?"mg/L":"n".equals(field)?"count":Arrays.asList("target","activity","female","sero","complete").contains(field)?"ratio":Arrays.asList("age","duration").contains(field)?"years":"schemeDurationMonths".equals(field)?"months":Arrays.asList("patientId","studyNo").contains(field)?"text":"genericDrugIds".equals(field)?"codes":"category";out.add(field+":"+unit);}return String.join(";",out);}
    private static void cancelled(){if(Thread.currentThread().isInterrupted())throw new CohortException(503,"SERVICE_UNAVAILABLE","导出暂不可用");}
    private String encode(Object v,int max)throws IOException {String s=json.writeValueAsString(v);if(s.codePointCount(0,s.length())>max)throw new IllegalStateException("导出摘要超限");return s;}
    public static Map<String,Object> conditions(AiExportQuery q,Map<String,Object> payload){if("COHORT".equals(q.source))return sideConditions(payload);Map<String,Object> out=new LinkedHashMap<>();for(String side:Arrays.asList("a","b")){Map<String,Object> original=map(payload.get(side)),safe=new LinkedHashMap<>();for(String field:Arrays.asList("source","cohortId","cohortVersion"))safe.put(field,original.get(field));safe.putAll(sideConditions(original));out.put(side,safe);}out.put("excludeOverlap",payload.get("excludeOverlap"));out.put("overlapN",payload.get("overlapN"));return out;}
    private static Map<String,Object> sideConditions(Map<String,Object> payload){Map<String,Object> filters=map(payload.get("filters")),safe=new LinkedHashMap<>();for(String key:Arrays.asList("studyCode","at","act","sex","age","sero","cm","tx","data"))safe.put(key,filters.get(key));Map<String,Object> ids=new LinkedHashMap<>();boolean explicit=filters.get("ids")!=null;ids.put("mode",explicit?"EXPLICIT":"ALL");ids.put("submittedUniqueIdsN",explicit?payload.get("submittedUniqueIdsN"):null);ids.put("effectiveIdsN",explicit?payload.get("effectiveIdsN"):null);Map<String,Object> out=new LinkedHashMap<>();out.put("filters",safe);out.put("ids",ids);return out;}
    public void finishWriteFailed(long owner,String trace){try{if(!Thread.currentThread().isInterrupted())audit.finishWriteFailed(trace,owner,clock.instant().toEpochMilli());}catch(RuntimeException e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("export trace={} operation=finishWriteFailed errorCode=RESPONSE_WRITE_FAILED",trace);}}
    public void finishWritten(long owner,String trace){try{if(!Thread.currentThread().isInterrupted())audit.finishWritten(trace,owner,clock.instant().toEpochMilli());}catch(RuntimeException e){org.slf4j.LoggerFactory.getLogger(getClass()).warn("export trace={} operation=finishWritten errorCode=SERVICE_UNAVAILABLE",trace);}}
}
